import json
from pathlib import Path

ROOT = Path(__file__).resolve().parents[3]
PACKET = json.loads((ROOT / 'tools/trajectory-inspector/dist/packet.js').read_text().removeprefix('window.PACKET = ').strip().removesuffix(';'))
REVIEWS = {}
CATEGORIES = ['condition', 'action', 'exception', 'rationale', 'notes', 'other']


def trajectory(h, evolution, summary):
    REVIEWS[h] = dict(read=[], complete=False, evolution=evolution, summary=summary, rounds={})


def entry(category, text, quote='', types='n', source=None):
    return category, text, quote, types, source


def code(h, r, *observations):
    entries = []
    for category, text, quote, types, source in observations:
        quotes = []
        for q in ([quote] if isinstance(quote, str) else quote):
            if q:
                qr = source or r
                original = PACKET['trajectories'][int(h[1:])-1]['rounds'][qr-1]['text']
                assert q in original, (h, r, qr, q)
                quotes.append(dict(round=qr, text=q))
        entries.append(dict(id=f'ai-{h}-{r}-{len(entries)+1}', category=category, text=text,
                            types=[{'n':'narrated','e':'explicit','a':'ambiguous'}[t] for t in types], quotes=quotes))
    absent = {
        'condition': 'No explicit additional if/when trigger for changing the strategy is stated; the advice concerns the ordinary sender and receiver roles.',
        'exception': 'No concrete stopping, punishment, or recovery rule is specified in this round.',
        'other': 'No additional observation coded beyond the entries above.',
    }
    for category in CATEGORIES:
        if not any(e['category'] == category for e in entries):
            assert category in absent, (h, r, category)
            entries.append(dict(id=f'ai-{h}-{r}-{category}-absence', category=category, text=absent[category], types=[], quotes=[]))
    REVIEWS[h]['rounds'][str(r)] = dict(entries=entries)


