def build():
    assert set(REVIEWS) == {t['id'] for t in PACKET['trajectories']}
    for h, review in REVIEWS.items():
        assert set(review['rounds']) == {str(r) for r in range(1,11)}, h
        assert not review['read'] and review['complete'] is False
        for note in review['rounds'].values():
            assert {e['category'] for e in note['entries']} == set(CATEGORIES)
        # Give comparison notes an earlier-round anchor as well as current evidence.
        # These are the already-curated preceding actions, not inferred new evidence.
        for r in range(2,11):
            if h == 'H07' and r in (3,4):
                continue
            previous = [q for e in review['rounds'][str(r-1)]['entries'] if e['category']=='action' for q in e['quotes']]
            for e in review['rounds'][str(r)]['entries']:
                if e['category']=='notes':
                    for q in previous:
                        if q not in e['quotes']:
                            e['quotes'].append(q.copy())
    bundle = dict(schema_version=2, packet_id=PACKET['id'], source_sha256=PACKET['source_sha256'],
                  provenance=dict(author='Codex AI draft', generated_date='2026-10-03',
                                  status='awaiting_human_review', source='Complete frozen 120-myth packet',
                                  scope='Textual reading only; no behavioral or causal validation. Prior audit summaries were available to the reader.',
                                  independence='AI-assisted review, not independent blinded human validation.'), reviews=REVIEWS)
    path = Path(__file__).with_name('ai_reading_packet.json')
    path.write_text(json.dumps(bundle,ensure_ascii=False,indent=2)+'\n')
    (ROOT/'tools/trajectory-inspector/dist/ai-drafts.js').write_text('window.AI_DRAFTS = '+json.dumps(bundle,ensure_ascii=False)+';\n')
    print(json.dumps(dict(trajectories=len(REVIEWS),rounds=sum(len(r['rounds']) for r in REVIEWS.values()),
                         entries=sum(len(n['entries']) for r in REVIEWS.values() for n in r['rounds'].values()),
                         exact_quotes=sum(len(e['quotes']) for r in REVIEWS.values() for n in r['rounds'].values() for e in n['entries']))))


if __name__ == '__main__':
    build()
